import{_ as i,a0 as l,w as o,s as r,I as n,x as a,a1 as e,A as p,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const q=JSON.parse('{"title":"用 Bash 脚本发送新用户帐户创建的邮件 | LCTT x X-CMD","titleTemplate":false,"description":"用 Bash 脚本发送新用户帐户创建的邮件 | LCTT (201909) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 Bash 脚本发送新用户帐户创建的邮件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 Bash 脚本发送新用户帐户创建的邮件 | LCTT (201909) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201909/20190912 Bash Script to Send a Mail About New User Account Creation","title":"用 Bash 脚本发送新用户帐户创建的邮件","tag":"201909","desc":""},"relativePath":"201909/20190912 Bash Script to Send a Mail About New User Account Creation.md","filePath":"[post].md"}'),u={name:"201909/20190912 Bash Script to Send a Mail About New User Account Creation.md"};function g(h,s,c,m,b,k){const t=l("Link");return o(),r("div",null,[s[17]||(s[17]=n("h1",{id:"用-bash-脚本发送新用户帐户创建的邮件",tabindex:"-1"},[a("用 Bash 脚本发送新用户帐户创建的邮件 "),n("a",{class:"header-anchor",href:"#用-bash-脚本发送新用户帐户创建的邮件","aria-label":"Permalink to “用 Bash 脚本发送新用户帐户创建的邮件”"},"​")],-1)),s[18]||(s[18]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/201909/20/093308a615tcuiopctvp5t.jpg",alt:""})],-1)),s[19]||(s[19]=n("p",null,"出于某些原因，你可能需要跟踪 Linux 上的新用户创建信息。同时，你可能需要通过邮件发送详细信息。这或许是审计目标的一部分，或者安全团队出于跟踪目的可能希望对此进行监控。",-1)),s[20]||(s[20]=n("p",null,"我们可以通过其他方式进行此操作，正如我们在上一篇文章中已经描述的那样。",-1)),n("ul",null,[n("li",null,[e(t,{href:"https://www.2daygeek.com/linux-bash-script-to-monitor-user-creation-send-email/"},{default:p(()=>[...s[0]||(s[0]=[a("在系统中创建新用户帐户时发送邮件的 Bash 脚本",-1)])]),_:1})])]),s[21]||(s[21]=n("p",null,"Linux 有许多开源监控工具可以使用。但我不认为他们有办法跟踪新用户创建过程，并在发生时提醒管理员。",-1)),s[22]||(s[22]=n("p",null,"那么我们怎样才能做到这一点？",-1)),s[23]||(s[23]=n("p",null,"我们可以编写自己的 Bash 脚本来实现这一目标。我们过去写过许多有用的 shell 脚本。如果你想了解，请进入下面的链接。",-1)),n("ul",null,[n("li",null,[e(t,{href:"https://www.2daygeek.com/category/shell-script/"},{default:p(()=>[...s[1]||(s[1]=[a("如何使用 shell 脚本自动化日常活动？",-1)])]),_:1})])]),s[24]||(s[24]=d(`<h3 id="这个脚本做了什么" tabindex="-1">这个脚本做了什么？ <a class="header-anchor" href="#这个脚本做了什么" aria-label="Permalink to “这个脚本做了什么？”">​</a></h3><p>这将每天两次（一天的开始和结束）备份 <code>/etc/passwd</code> 文件，这将使你能够获取指定日期的新用户创建详细信息。</p><p>我们需要添加以下两个 cron 任务来复制 <code>/etc/passwd</code> 文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># crontab -e</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1 0 * * * cp /etc/passwd /opt/scripts/passwd-start-$(date +&quot;%Y-%m-%d&quot;)</span></span>
<span class="line"><span>59 23 * * * cp /etc/passwd /opt/scripts/passwd-end-$(date +&quot;%Y-%m-%d&quot;)</span></span></code></pre></div><p>它使用 <code>diff</code> 命令来检测文件之间的差异，如果发现与昨日有任何差异，脚本将向指定 email 发送新用户详细信息。</p><p>我们不用经常运行此脚本，因为用户创建不经常发生。但是，我们计划每天运行一次此脚本。</p><p>这样，你可以获得有关新用户创建的综合报告。</p><p><strong>注意：</strong>我们在脚本中使用了我们的电子邮件地址进行演示。因此，我们要求你用自己的电子邮件地址。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vi /opt/scripts/new-user-detail.sh</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span>mv /opt/scripts/passwd-start-$(date --date=&#39;yesterday&#39; &#39;+%Y-%m-%d&#39;) /opt/scripts/passwd-start</span></span>
<span class="line"><span>mv /opt/scripts/passwd-end-$(date --date=&#39;yesterday&#39; &#39;+%Y-%m-%d&#39;) /opt/scripts/passwd-end</span></span>
<span class="line"><span>ucount=$(diff /opt/scripts/passwd-start /opt/scripts/passwd-end | grep &quot;&gt;&quot; | cut -d&quot;:&quot; -f6 | cut -d&quot;/&quot; -f3 | wc -l)</span></span>
<span class="line"><span>if [ $ucount -gt 0 ]</span></span>
<span class="line"><span>then</span></span>
<span class="line"><span>  SUBJECT=&quot;ATTENTION: New User Account is created on server : \`date --date=&#39;yesterday&#39; &#39;+%b %e&#39;\`&quot;</span></span>
<span class="line"><span>  MESSAGE=&quot;/tmp/new-user-logs.txt&quot;</span></span>
<span class="line"><span>  TO=&quot;2daygeek@gmail.com&quot;</span></span>
<span class="line"><span>  echo  &quot;Hostname: \`hostname\`&quot; &gt;&gt; $MESSAGE</span></span>
<span class="line"><span>  echo -e &quot;\\n&quot; &gt;&gt; $MESSAGE</span></span>
<span class="line"><span>  echo &quot;The New User Details are below.&quot; &gt;&gt; $MESSAGE</span></span>
<span class="line"><span>  echo &quot;+------------------------------+&quot; &gt;&gt; $MESSAGE</span></span>
<span class="line"><span>  diff /opt/scripts/passwd-start /opt/scripts/passwd-end | grep &quot;&gt;&quot; | cut -d&quot;:&quot; -f6 | cut -d&quot;/&quot; -f3 &gt;&gt;  $MESSAGE</span></span>
<span class="line"><span>  echo &quot;+------------------------------+&quot; &gt;&gt; $MESSAGE</span></span>
<span class="line"><span>  mail -s &quot;$SUBJECT&quot; &quot;$TO&quot; &lt; $MESSAGE</span></span>
<span class="line"><span>  rm $MESSAGE</span></span>
<span class="line"><span>fi</span></span></code></pre></div><p>给 <code>new-user-detail.sh</code> 文件添加可执行权限。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod +x /opt/scripts/new-user-detail.sh</span></span></code></pre></div><p>最后添加一个 cron 任务来自动执行此操作。它在每天早上 7 点运行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># crontab -e</span></span>
<span class="line"><span></span></span>
<span class="line"><span>0 7 * * * /bin/bash /opt/scripts/new-user.sh</span></span></code></pre></div><p><strong>注意：</strong>你会在每天早上 7 点都会收到一封关于昨日详情的邮件提醒。</p><p><strong>输出：</strong>输出与下面的输出相同。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cat /tmp/new-user-logs.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Hostname: CentOS.2daygeek.com</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The New User Details are below.</span></span>
<span class="line"><span>+------------------------------+</span></span>
<span class="line"><span>tuser3</span></span>
<span class="line"><span>+------------------------------+</span></span></code></pre></div><hr>`,17)),n("p",null,[s[3]||(s[3]=a("via: ",-1)),e(t,{href:"https://www.2daygeek.com/linux-shell-script-to-monitor-user-creation-send-email/"},{default:p(()=>[...s[2]||(s[2]=[a("https://www.2daygeek.com/linux-shell-script-to-monitor-user-creation-send-email/",-1)])]),_:1})]),n("p",null,[s[8]||(s[8]=a("作者：",-1)),e(t,{href:"https://www.2daygeek.com/author/magesh/"},{default:p(()=>[...s[4]||(s[4]=[a("Magesh Maruthamuthu",-1)])]),_:1}),s[9]||(s[9]=a(" 选题：",-1)),e(t,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[5]||(s[5]=[a("lujun9972",-1)])]),_:1}),s[10]||(s[10]=a(" 译者：",-1)),e(t,{href:"https://github.com/geekpi"},{default:p(()=>[...s[6]||(s[6]=[a("geekpi",-1)])]),_:1}),s[11]||(s[11]=a(" 校对：",-1)),e(t,{href:"https://github.com/wxy"},{default:p(()=>[...s[7]||(s[7]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[14]||(s[14]=a("本文由 ",-1)),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[12]||(s[12]=[a("LCTT",-1)])]),_:1}),s[15]||(s[15]=a(" 原创编译，",-1)),e(t,{href:"https://linux.cn/"},{default:p(()=>[...s[13]||(s[13]=[a("Linux中国",-1)])]),_:1}),s[16]||(s[16]=a(" 荣誉推出",-1))])])}const S=i(u,[["render",g]]);export{q as __pageData,S as default};
